<template>
    <el-table :data="recordsList" v-if="activeName == '1'" style="width: 100%">
      <el-table-column label="标识符" align="center" prop="identifier">
      </el-table-column>
      <el-table-column label="最新值" align="center" prop="ai_value">
      </el-table-column>
      <el-table-column label="报警时间" align="center" prop="time" />
    </el-table>
    <el-table :data="AiValueList" v-else style="width: 100%">
      <el-table-column label="标识符" align="center" prop="identifier">
      </el-table-column>
      <el-table-column label="最新值" align="center" prop="value">
      </el-table-column>
      <el-table-column label="时间" align="center" prop="time" />
    </el-table>
</template>

<script>
export default {
  props: {
    chooseItem: {
      type: Object,
      default: () => ({}),
    },
    activeName: {
      type: String,
    },
    recordsList: {
      type: Array,
      default: () => [],
    },
    AiValueList: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      chooseItemInfo: {},
      attributeTotal: 0,
      attributeParams: {
        page: 1,
        size: 10,
      },
    };
  },
  created() {
    this.chooseItemInfo = { ...this.chooseItem };
  },
  methods: {
    parsedData(row) {
      try {
        return JSON.parse(row.ai_value) || [];
      } catch (e) {
        console.error("解析ai_value失败:", e);
        return [];
      }
    },
    shouldShowMore(row) {
      return this.parsedData(row).length > 4;
    },
  },
};
</script>

